import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))
    x = int(data[1+n])

    arr.sort()

    print(' '.join(map(str, arr)))

    if n % 2 == 1:
        median = arr[n // 2]
    else:
        median = (arr[n // 2 - 1] + arr[n // 2]) / 2.0

    print(median)

    left, right = 0, n - 1
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            result = mid
            break
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    print(result)

if __name__ == "__main__":
    main()
